using System.Globalization;
using System.Text.RegularExpressions;
using System.Xml.Linq;
using Syncfusion.Pdf.Graphics;

namespace FatturaFacile.Infrastructure.Reporting;

/// <summary>
/// Paints the QR-bill SVG generated by the application (rect, line, text and path elements in millimetres)
/// on a PDF page as vector graphics, keeping the exact positions and sizes required by the Swiss Payment Standards.
/// </summary>
public static partial class QrBillPdfPainter
{
    private const float PointsPerMillimetre = 72f / 25.4f;

    [GeneratedRegex(@"[MHVLhvlZz]|-?\d+(?:\.\d+)?", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: 1000)]
    private static partial Regex PathTokens { get; }

    /// <summary>
    /// Paints the QR-bill.
    /// </summary>
    /// <param name="graphics">The page graphics (origin top-left, points).</param>
    /// <param name="svg">The QR-bill SVG (210 x 105 mm).</param>
    /// <param name="offsetYMillimetres">The vertical position of the QR-bill top edge on the page.</param>
    /// <exception cref="FormatException">When the SVG has no root element.</exception>
    public static void Paint(PdfGraphics graphics, string svg, float offsetYMillimetres)
    {
        ArgumentNullException.ThrowIfNull(graphics);
        ArgumentException.ThrowIfNullOrWhiteSpace(svg);

        var root = XDocument.Parse(svg).Root ?? throw new FormatException("SVG della QR-bill non valido.");

        foreach (var element in root.Elements())
        {
            Action<PdfGraphics, XElement, float>? painter = element.Name.LocalName switch
            {
                "rect" => PaintRectangle,
                "line" => PaintLine,
                "text" => PaintText,
                "path" => PaintPath,
                _ => null,
            };

            painter?.Invoke(graphics, element, offsetYMillimetres);
        }
    }

    private static float Mm(float millimetres) => millimetres * PointsPerMillimetre;

    private static float Number(XElement element, string attribute, float fallback = 0f)
    {
        var value = (string?)element.Attribute(attribute);
        return value is null ? fallback : float.Parse(value.Replace("pt", string.Empty, StringComparison.Ordinal), CultureInfo.InvariantCulture);
    }

    private static PdfBrush Brush(string? color) => string.Equals(color, "#ffffff", StringComparison.OrdinalIgnoreCase)
        ? PdfBrushes.White
        : PdfBrushes.Black;

    private static void PaintRectangle(PdfGraphics graphics, XElement element, float offsetY)
    {
        graphics.DrawRectangle(
            Brush((string?)element.Attribute("fill")),
            Mm(Number(element, "x")),
            Mm(Number(element, "y") + offsetY),
            Mm(Number(element, "width")),
            Mm(Number(element, "height")));
    }

    private static void PaintLine(PdfGraphics graphics, XElement element, float offsetY)
    {
        PdfPen pen = new(PdfBrushes.Black, Mm(Number(element, "stroke-width", 0.2f)));

        if (element.Attribute("stroke-dasharray") is not null)
        {
            pen.DashStyle = PdfDashStyle.Dash;
        }

        graphics.DrawLine(
            pen,
            Mm(Number(element, "x1")),
            Mm(Number(element, "y1") + offsetY),
            Mm(Number(element, "x2")),
            Mm(Number(element, "y2") + offsetY));
    }

    private static void PaintText(PdfGraphics graphics, XElement element, float offsetY)
    {
        var size = Number(element, "font-size", 8f);
        var bold = string.Equals((string?)element.Attribute("font-weight"), "bold", StringComparison.Ordinal);
        PdfStandardFont font = new(PdfFontFamily.Helvetica, size, bold ? PdfFontStyle.Bold : PdfFontStyle.Regular);
        var text = element.Value;
        var x = Mm(Number(element, "x"));

        if (string.Equals((string?)element.Attribute("text-anchor"), "end", StringComparison.Ordinal))
        {
            x -= font.MeasureString(text).Width;
        }

        // SVG y is the baseline; PDF strings are positioned by their top edge (Helvetica ascent ≈ 0.77 em).
        var top = Mm(Number(element, "y") + offsetY) - (size * 0.77f);
        graphics.DrawString(text, font, PdfBrushes.Black, x, top);
    }

    private static void PaintPath(PdfGraphics graphics, XElement element, float offsetY)
    {
        PdfPath path = new();

        foreach (var figure in ParseFigures((string?)element.Attribute("d") ?? string.Empty))
        {
            path.StartFigure();

            for (var i = 1; i < figure.Points.Count; i++)
            {
                var (x1, y1) = figure.Points[i - 1];
                var (x2, y2) = figure.Points[i];
                path.AddLine(Mm(x1), Mm(y1 + offsetY), Mm(x2), Mm(y2 + offsetY));
            }

            if (figure.Closed)
            {
                path.CloseFigure();
            }
        }

        var fill = (string?)element.Attribute("fill");

        if (string.Equals(fill, "none", StringComparison.OrdinalIgnoreCase))
        {
            graphics.DrawPath(new PdfPen(PdfBrushes.Black, Mm(Number(element, "stroke-width", 0.26f))), path);
        }
        else
        {
            graphics.DrawPath(Brush(fill), path);
        }
    }

    /// <summary>
    /// Parses the subset of SVG path commands used by the QR-bill renderer (M, L, H, V, their relative forms and Z).
    /// </summary>
    /// <param name="data">The path data.</param>
    /// <returns>The figures.</returns>
    private static List<QrBillPathFigure> ParseFigures(string data)
    {
        var tokens = PathTokens.Matches(data).Select(static m => m.Value).ToList();
        List<QrBillPathFigure> figures = [];
        QrBillPathFigure? current = null;
        var command = 'M';
        var index = 0;

        while (index < tokens.Count)
        {
            if (char.IsLetter(tokens[index][0]))
            {
                command = tokens[index][0];
                index++;
            }

            if (command is 'z' or 'Z')
            {
                if (current is not null)
                {
                    current.Closed = true;
                    current.Points.Add(current.Points[0]);
                }

                command = 'M';
                continue;
            }

            if (command == 'M')
            {
                current = new QrBillPathFigure();
                current.Points.Add((Value(tokens, index), Value(tokens, index + 1)));
                figures.Add(current);
                index += 2;
                command = 'L';
                continue;
            }

            index = AddSegment(current, command, tokens, index);
        }

        return figures;
    }

    private static int AddSegment(QrBillPathFigure? figure, char command, List<string> tokens, int index)
    {
        if (figure is null)
        {
            return index + 1;
        }

        var (x, y) = figure.Points[^1];
        var (point, consumed) = command switch
        {
            'L' => ((Value(tokens, index), Value(tokens, index + 1)), 2),
            'l' => ((x + Value(tokens, index), y + Value(tokens, index + 1)), 2),
            'H' => ((Value(tokens, index), y), 1),
            'h' => ((x + Value(tokens, index), y), 1),
            'V' => ((x, Value(tokens, index)), 1),
            'v' => ((x, y + Value(tokens, index)), 1),
            _ => ((x, y), 1),
        };

        figure.Points.Add(point);
        return index + consumed;
    }

    private static float Value(List<string> tokens, int index) => float.Parse(tokens[index], CultureInfo.InvariantCulture);
}
